          "find -print0 and -prune (don't recurse into dirs)",
          "find -exec CMD {} \\; vs -exec CMD {} + (batched)",
          "xargs: -0 (NUL-safe), -I {} (placeholder), -n N (batch size), -P N (parallel)",
