        "code": "import { Component, ChangeDetectionStrategy, signal, computed } from '@angular/core';\n\n@Component({\n  selector: 'app-counter-onpush',\n  standalone: true,\n  changeDetection: ChangeDetectionStrategy.OnPush,\n  template: `\n    <h1>{{ count() }}</h1>\n    <button (click)=\"count.set(count() + 1)\">+1</button>\n    <p>Doubled: {{ doubled() }}</p>\n  `,\n})\nexport class CounterOnPushComponent {\n  count = signal(0);\n  // computed is memoized — re-runs only when count() changes\n  doubled = computed(() => this.count() * 2);\n}",
